                if not G.busy() and M.try() then
                    local start = hrp() and hrp().CFrame
                    pcall(H.hatch, n.Name)
                    if start then M.hop(start.Position) end
                    M.free()
                end
            else S.task = L["Rebirth: "] .. egg .. L[" hatching in "] .. math.max(0, math.floor((n:GetAttribute("HatchAt") or 0) - G.now())) .. "s" end
