    if #list == 0 then S.task = L["Rebirth: waiting for a real "] .. egg .. L[" egg"] return end
    local best
    for _, e in ipairs(list) do
        local ok = B.safe(e)
        if ok == nil and on("f_scan") and (B.scanFail[e.id] or 0) < os.clock() then
            if not M.try() then return end
            local start = hrp() and hrp().CFrame
