            if B.didMove and start then M.hop(start.Position) end
            B.didMove = false
            M.free()
            if ok == nil then B.scanFail[e.id] = os.clock() + 8 end
        end
        if ok == true then best = e break end
    end
    if not best then S.task = L["Rebirth: making sure the "] .. egg .. L[" egg is real"] return end
    if not M.try() then return end
    local start = hrp() and hrp().CFrame
    local moved = false
    pcall(function()
        S.task = L["Rebirth: getting "] .. egg
