    for _, p in ipairs(pts) do ds[#ds + 1] = Vector3.new(p.X - cx, 0, p.Z - cz).Magnitude end
    table.sort(ds)
    local rad = ds[math.max(1, math.floor(#ds * 0.85))] or 30
