    if CONFIG.DISCORD_INVITE ~= "" then
        HG:AddButton({ Text = L["Copy Discord Invite"], Func = function() pcall(setclipboard, CONFIG.DISCORD_INVITE); notify(L["Discord link copied"]) end })
    end
    local CG = Tab:AddRightGroupbox(L["Changelog"], "list")
    CG:AddLabel('<font color="#f5c542"><b>2026-10-27  v1.4</b></font>', true)
    for _, l in ipairs({ L["+ Auto haunt pets"], L["+ Haunt timer"], L["+ Walk when hit"], L["* No ESP flashes"] }) do CG:AddLabel(l, true) end
    CG:AddLabel('<font color="#9aa0a6"><b>2026-10-27  v1.3</b></font>', true)
    for _, l in ipairs({ L["+ Rainbow/type pick"], L["+ Trait egg filter"], L["+ Food buy menu"], L["+ Scanner menu"], L["+ Grab best egg"], L["+ No knockback"], L["* Anti steal fix"], L["* Trait values"] }) do CG:AddLabel(l, true) end
